function productOfOthers(nums: number[]): number[] {
  const out: number[] = [];
  for (let i = 0; i < nums.length; i++) {
    let p = 1;
    for (let j = 0; j < nums.length; j++) if (j !== i) p *= nums[j];
    out.push(p);
  }
  return out;
}

